#!/usr/bin/env python3
"""
Round 154b (culprits), 4 October 2026. Needs round 153b.

Paints the Woodlands basemap as a watercolour.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 154b (4 October)\n\nNeeds round 153b. No tiles patch. No app.js?v= bump. Woodlands basemap as a watercolour.\n\n- Owner on 152b/153b: too many flat colours, programmatic not handmade\n  watercolour; tans against greens spotty, not soft diffused golden light.\n- woodPaintPixels redone: the Kuwahara flat strokes are gone. Plants and bare\n  ground blend over several pixels (greenness blurred), colour bleeds softly\n  (55% of a blur), a darker rim where a wash meets a lighter one, the paper's\n  faint grain (woodGrain, by world pixel, seamless) with pigment settling\n  more in the darks, the warm paper showing through lighter washes\n  (WOOD.paper), a warm golden glaze (WOOD.glaze). Earth ramp moved toward\n  olive-tan so tans and greens sit together; contrast gentler; hillshade\n  shadow softer, light warmer. Checked on sample satellite pictures; not seen\n  live.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round154b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 153b" not in h.read_text(encoding="utf-8"):
        sys.exit("round154b: round 153b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round154b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round154b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round154b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
